  if let Err(error)=member.admit_snapshot_read_owner(snapshot){return CapturedMemberRetirementAdmission::Rejected{captured,refusal:CapturedMemberRetirementRefusal::Identity(error)}}
  let matches=member.member_snapshot_identity().is_some_and(|identity|identity.artifact_id==value.reference.artifact_id&&identity.dialect==&value.reference.dialect&&identity.owner.is_none_or(|owner|owner==&value.owner));
