   Ok(active)=>CapturedMemberRetirementAdmission::Ready(CapturedMemberSnapshotRetirement{captured:std::mem::ManuallyDrop::new(Some(captured)),active:std::mem::ManuallyDrop::new(Some(active)),metadata:std::mem::ManuallyDrop::new(None),require_member_terminal}),
   Err(rejected)=>{
